import React from "react";
import { action } from "@storybook/addon-actions";
import { ColorModeProvider } from "../../lib/styling";
import Button from "../Button";
import Inline from "../Inline";
import Stack from "../Stack";
import SearchInput from "./SearchInput";
import type { Meta, StoryObj } from "@storybook/react";
import RadioGroup from "../RadioGroup";
import Radio from "../Radio";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof SearchInput> = {
  id: "Components/SearchInput",
  title: "Components/Search Input",
  component: SearchInput,
  args: {
    placeholder: "Search",
  },
  render: (args) => (
    <SearchInput
      {...args}
      placeholder="Search"
      onSearch={action("onSearch")}
      onChange={action("onChange")}
    />
  ),
};

export default meta;
type Story = StoryObj<typeof SearchInput>;

export const Basic: Story = {
  tags: ["visual-test"],
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
};

export const Controlled: Story = {
  render: () => {
    const [value, setValue] = React.useState("");
    const submit = () => alert(`Submit value: "${value}"`);
    return (
      <Stack spacing="2-x">
        <SearchInput
          placeholder="Search"
          value={value}
          onSearch={(newValue) => {
            setValue(newValue);
            submit();
          }}
          onChange={(evt, newValue) => setValue(newValue)}
        />
        <Inline spacing="2-x">
          <Button onClick={() => setValue("")}>Clear</Button>
          <Button variant="primary" onClick={submit}>
            Submit
          </Button>
        </Inline>
      </Stack>
    );
  },
};

export const LargeUntil: Story = {
  render: () => {
    const [largeUntil, setLargeUntil] = React.useState();
    return (
      <Stack spacing="2-x">
        <SearchInput
          placeholder="Search"
          onSearch={action("onSearch")}
          onChange={action("onChange")}
          largeUntil={largeUntil || "xs"}
        />
        <RadioGroup
          name="breakpoints"
          row
          value={largeUntil || "xs"}
          onChange={(e, value) => setLargeUntil(value)}
          style={{ marginBottom: 16 }}
        >
          <Radio value="xxs" label="xxs" />
          <Radio value="xs" label="xs" />
          <Radio value="sm" label="sm" />
          <Radio value="md" label="md" />
          <Radio value="lg" label="lg" />
        </RadioGroup>
      </Stack>
    );
  },
};

export const Sizes: Story = {
  render: () => (
    <Stack spacing="2-x">
      <SearchInput
        size="xsmall"
        placeholder="Small"
        onSearch={action("onSearch")}
        onChange={action("onChange")}
      />
      <SearchInput
        size="small"
        placeholder="Small"
        onSearch={action("onSearch")}
        onChange={action("onChange")}
      />
      <SearchInput
        size="medium"
        placeholder="Medium"
        onSearch={action("onSearch")}
        onChange={action("onChange")}
      />
      <SearchInput
        size="large"
        placeholder="Large"
        onSearch={action("onSearch")}
        onChange={action("onChange")}
      />
      <SearchInput
        size="xlarge"
        placeholder="Large"
        onSearch={action("onSearch")}
        onChange={action("onChange")}
      />
    </Stack>
  ),
};

export const Debounce: Story = {
  render: () => {
    const [value, setValue] = React.useState("");
    return (
      <Stack spacing="2-x">
        <SearchInput
          debounce={500}
          placeholder="Search"
          onChange={(evt, value) => {
            action("onChange");
            setValue(value);
          }}
        />
        <div>Debounced search value: {value}</div>
      </Stack>
    );
  },
};
